
DROP SCHEMA IF EXISTS core CASCADE;
CREATE SCHEMA core;
SET search_path TO core, public;

CREATE TABLE core.categories (
    category_id         VARCHAR(10) PRIMARY KEY,
    category_name       VARCHAR(120) NOT NULL,
    parent_category_id  VARCHAR(10),
    created_at          TIMESTAMPTZ NOT NULL,
    updated_at          TIMESTAMPTZ NOT NULL,
    CONSTRAINT chk_categories_updated_at CHECK (updated_at >= created_at)
);

CREATE TABLE core.customers (
    customer_id         VARCHAR(12) PRIMARY KEY,
    full_name           VARCHAR(150) NOT NULL,
    email               VARCHAR(200) NOT NULL,
    phone               VARCHAR(30),
    city                VARCHAR(100),
    customer_segment    VARCHAR(30) NOT NULL,
    status              VARCHAR(20) NOT NULL,
    source_system       VARCHAR(50) NOT NULL DEFAULT 'unknown',
    ingested_at         TIMESTAMPTZ NOT NULL DEFAULT now(),
    created_at          TIMESTAMPTZ NOT NULL,
    updated_at          TIMESTAMPTZ NOT NULL,
    CONSTRAINT uq_customers_email UNIQUE (email),
    CONSTRAINT chk_customers_status CHECK (status IN ('active','inactive')),
    CONSTRAINT chk_customers_updated_at CHECK (updated_at >= created_at)
);

CREATE TABLE core.products (
    product_id          VARCHAR(12) PRIMARY KEY,
    category_id         VARCHAR(10) NOT NULL,
    product_name        VARCHAR(200) NOT NULL,
    unit_price          NUMERIC(14,2) NOT NULL,
    cost_price          NUMERIC(14,2) NOT NULL,
    status              VARCHAR(20) NOT NULL,
    source_system       VARCHAR(50) NOT NULL DEFAULT 'unknown',
    ingested_at         TIMESTAMPTZ NOT NULL DEFAULT now(),
    created_at          TIMESTAMPTZ NOT NULL,
    updated_at          TIMESTAMPTZ NOT NULL,
    CONSTRAINT chk_products_unit_price CHECK (unit_price >= 0),
    CONSTRAINT chk_products_cost_price CHECK (cost_price >= 0),
    CONSTRAINT chk_products_status CHECK (status IN ('active','inactive','discontinued')),
    CONSTRAINT chk_products_updated_at CHECK (updated_at >= created_at)
);

CREATE TABLE core.orders (
    order_id            VARCHAR(12) PRIMARY KEY,
    customer_id         VARCHAR(12) NOT NULL,
    order_date          TIMESTAMPTZ NOT NULL,
    status              VARCHAR(20) NOT NULL,
    shipping_city       VARCHAR(100),
    channel             VARCHAR(20) NOT NULL,
    order_total         NUMERIC(14,2) NOT NULL,
    source_system       VARCHAR(50) NOT NULL DEFAULT 'unknown',
    ingested_at         TIMESTAMPTZ NOT NULL DEFAULT now(),
    created_at          TIMESTAMPTZ NOT NULL,
    updated_at          TIMESTAMPTZ NOT NULL,
    CONSTRAINT chk_orders_status CHECK
        (status IN ('pending','confirmed','shipped','completed','cancelled')),
    CONSTRAINT chk_orders_channel CHECK
        (channel IN ('web','mobile_app','social')),
    CONSTRAINT chk_orders_total CHECK (order_total >= 0),
    CONSTRAINT chk_orders_updated_at CHECK (updated_at >= created_at)
);

CREATE TABLE core.order_items (
    order_item_id       VARCHAR(16) PRIMARY KEY,
    order_id            VARCHAR(12) NOT NULL,
    product_id          VARCHAR(12) NOT NULL,
    quantity            INTEGER NOT NULL,
    unit_price          NUMERIC(14,2) NOT NULL,
    discount_amount     NUMERIC(14,2) NOT NULL DEFAULT 0,
    source_system       VARCHAR(50) NOT NULL DEFAULT 'unknown',
    ingested_at         TIMESTAMPTZ NOT NULL DEFAULT now(),
    created_at          TIMESTAMPTZ NOT NULL,
    updated_at          TIMESTAMPTZ NOT NULL,
    CONSTRAINT chk_order_items_quantity CHECK (quantity > 0),
    CONSTRAINT chk_order_items_unit_price CHECK (unit_price >= 0),
    CONSTRAINT chk_order_items_discount CHECK (discount_amount >= 0),
    CONSTRAINT chk_order_items_discount_vs_gross
    CHECK (discount_amount <= unit_price * quantity),
    CONSTRAINT chk_order_items_updated_at CHECK (updated_at >= created_at)
);

CREATE TABLE core.payments (
    payment_id          VARCHAR(12) PRIMARY KEY,
    order_id            VARCHAR(12) NOT NULL,
    payment_date        TIMESTAMPTZ NOT NULL,
    payment_method      VARCHAR(30) NOT NULL,
    payment_status      VARCHAR(20) NOT NULL,
    amount              NUMERIC(14,2) NOT NULL,
    source_system       VARCHAR(50) NOT NULL DEFAULT 'unknown',
    ingested_at         TIMESTAMPTZ NOT NULL DEFAULT now(),
    created_at          TIMESTAMPTZ NOT NULL,
    updated_at          TIMESTAMPTZ NOT NULL,
    CONSTRAINT chk_payments_method CHECK
        (payment_method IN ('cash','bank_transfer','card','e_wallet')),
    CONSTRAINT chk_payments_status CHECK
        (payment_status IN ('pending','success','failed','refunded')),
    CONSTRAINT chk_payments_amount CHECK (amount >= 0),
    CONSTRAINT chk_payments_updated_at CHECK (updated_at >= created_at)
);

-- ================================================================
-- LOAD DATA
-- Foreign keys are intentionally added AFTER this section.
-- ================================================================

-- categories: 20 rows

-- customers: 1000 rows



-- products: 500 rows


-- orders: 5000 rows













