-- payments: 4517 rows












-- ================================================================
-- ADD FOREIGN KEYS AFTER ALL DATA EXISTS
-- If any source row is orphaned, one of these statements will fail.
-- ================================================================

ALTER TABLE core.categories
    ADD CONSTRAINT fk_categories_parent
    FOREIGN KEY (parent_category_id)
    REFERENCES core.categories(category_id);

ALTER TABLE core.products
    ADD CONSTRAINT fk_products_category
    FOREIGN KEY (category_id)
    REFERENCES core.categories(category_id);

ALTER TABLE core.orders
    ADD CONSTRAINT fk_orders_customer
    FOREIGN KEY (customer_id)
    REFERENCES core.customers(customer_id);

ALTER TABLE core.order_items
    ADD CONSTRAINT fk_order_items_order
    FOREIGN KEY (order_id)
    REFERENCES core.orders(order_id)
    ON DELETE CASCADE;

ALTER TABLE core.order_items
    ADD CONSTRAINT fk_order_items_product
    FOREIGN KEY (product_id)
    REFERENCES core.products(product_id);

ALTER TABLE core.payments
    ADD CONSTRAINT fk_payments_order
    FOREIGN KEY (order_id)
    REFERENCES core.orders(order_id);

-- INDEXES
CREATE INDEX idx_products_category ON core.products(category_id);
CREATE INDEX idx_orders_customer ON core.orders(customer_id);
CREATE INDEX idx_orders_date ON core.orders(order_date);
CREATE INDEX idx_orders_status ON core.orders(status);
CREATE INDEX idx_order_items_order ON core.order_items(order_id);
CREATE INDEX idx_order_items_product ON core.order_items(product_id);
CREATE INDEX idx_payments_order ON core.payments(order_id);
CREATE INDEX idx_payments_date ON core.payments(payment_date);

-- ================================================================
-- VERIFY
-- ================================================================

SELECT 'categories' AS table_name, COUNT(*) AS row_count FROM core.categories
UNION ALL SELECT 'customers', COUNT(*) FROM core.customers
UNION ALL SELECT 'products', COUNT(*) FROM core.products
UNION ALL SELECT 'orders', COUNT(*) FROM core.orders
UNION ALL SELECT 'order_items', COUNT(*) FROM core.order_items
UNION ALL SELECT 'payments', COUNT(*) FROM core.payments;

SELECT
    COUNT(*) AS completed_orders,
    SUM(order_total) AS completed_revenue,
    ROUND(AVG(order_total), 2) AS aov
FROM core.orders
WHERE status = 'completed';


SELECT
    ROUND(
        100.0 * COUNT(*) FILTER (WHERE payment_status='success')
        / NULLIF(COUNT(*),0), 2
    ) AS payment_success_rate_pct
FROM core.payments;

WITH order_side AS (
    SELECT SUM(order_total) AS revenue
    FROM core.orders
    WHERE status='completed'
),
item_side AS (
    SELECT SUM(oi.quantity*oi.unit_price - oi.discount_amount) AS revenue
    FROM core.orders o
    JOIN core.order_items oi ON oi.order_id=o.order_id
    WHERE o.status='completed'
)
SELECT
    o.revenue AS order_revenue,
    i.revenue AS item_revenue,
    o.revenue-i.revenue AS difference
FROM order_side o
CROSS JOIN item_side i;


 
 











